import { ReactNode } from 'react';
import { z } from 'zod';

// 개별 독립 스키마 정의
export const bankInfoSchema = z.object({
  bankLabel: z.string(),
  bankCode: z.string().nullable().optional(),
  dfltAliasNm: z.string().nullable().optional(),
});

export const accountInfoSchema = z.object({
  label: z.string(),
  value: z.string().optional(),
  children: z.any().optional(), // 단순화된 children 검증
});

export const availableAmountSchema = z.object({
  amount: z.number(),
  label: z.string().optional(),
});

export const linkedAccountAmountSchema = z.object({
  amount: z.number().optional(),
});

export const wrapperSchema = z.object({
  children: z.any(), // React children
  className: z.string().optional(),
});

// 타입 내보내기
export type BankInfoProps = z.infer<typeof bankInfoSchema>;
export type AccountInfoProps = z.infer<typeof accountInfoSchema>;
export type AvailableAmountProps = z.infer<typeof availableAmountSchema>;
export type LinkedAccountAmountProps = z.infer<typeof linkedAccountAmountSchema>;
export type WrapperProps = z.infer<typeof wrapperSchema> & {
  children: ReactNode; // React 타입 추가
};
