import { memo, Fragment } from 'react';
import {
  bankInfoSchema,
  accountInfoSchema,
  availableAmountSchema,
  linkedAccountAmountSchema,
  wrapperSchema,
  BankInfoProps,
  AccountInfoProps,
  AvailableAmountProps,
  LinkedAccountAmountProps,
  WrapperProps,
} from '~/entities/exchange-input-amount/model/token-info-schema';
import i18n from '~/shared/i18n/i18n';
import { validateProps } from '~/shared/lib/schema/zod-utils';

// 컴포넌트 정의
export const TokenInfoBankInfo = memo(function TokenInfoBankInfo(props: BankInfoProps) {
  const {
    bankLabel: usingBankLabel,
    bankCode: usingBankCode,
    dfltAliasNm: defaultAliasName,
  } = validateProps(bankInfoSchema, props, 'TokenInfoBankInfo');

  return (
    <Fragment>
      |<span className={`wallet-account ${usingBankCode}`}>{defaultAliasName}</span>
    </Fragment>
  );
});

export const TokenInfoAccountInfo = memo(function TokenInfoAccountInfo(props: AccountInfoProps) {
  const { label, value, children } = validateProps(accountInfoSchema, props, 'TokenInfoAccountInfo');

  return (
    <div className="acnt-info">
      <p className="info">{label}</p>
      <div className="wallet-asset-info whs-normal">
        <span className="type text-end">{value}</span>
        {children}
      </div>
    </div>
  );
});

export const TokenInfoAvailableAmount = memo(function TokenInfoAvailableAmount(props: AvailableAmountProps) {
  const { amount, label } = validateProps(availableAmountSchema, props, 'TokenInfoAvailableAmount');

  return (
    <div className="acnt-info">
      <p className="info">{i18n.t('availableAmount', { transactionLabel: label })}</p>
      <span className="balance-info">
        <b id="acntBalance">{Number(amount)?.toLocaleString()}</b> {i18n.t('won')}
      </span>
    </div>
  );
});

export const TokenInfoLinkedAccountAmount = memo(function TokenInfoLinkedAccountAmount(
  props: LinkedAccountAmountProps,
) {
  const { amount } = validateProps(linkedAccountAmountSchema, props, 'TokenInfoLinkedAccountAmount');

  if (!amount || amount === 0) return null;

  return (
    <div className="acnt-info">
      <p className="info">{i18n.t('linkedAccountAmount')}</p>
      <span className="balance-info">
        <b id="acntBalance">{Number(amount)?.toLocaleString()}</b> {i18n.t('won')}
      </span>
    </div>
  );
});

export const TokenInfoWrapper = memo(function TokenInfoWrapper(props: WrapperProps) {
  const { children, className = 'app-info pay' } = validateProps(wrapperSchema, props, 'TokenInfoWrapper');
  return <div className={className}>{children}</div>;
});
